mapper.select:
SELECT *
FROM hr_audit_log
WHERE archived = 0
  AND create_time  <  #{beforeDate}
ORDER BY create_time ASC
LIMIT #{limit}

mapper.update:
UPDATE hr_audit_log
SET archived = 1,
    archive_time = #{archiveTime}
WHERE id IN

    #{id}

mapper.delete:
DELETE FROM hr_audit_log
WHERE archived = 1
  AND archive_time  <  #{beforeDate}
